import { type Attribute, type Prim, type Stage } from 'typescript-usd/usd'
import { NodeGraph } from './nodeGraph.ts'
import { UsdShadeTokens } from './tokens.ts'

/**
 * A Material provides a container into which multiple "render contexts"
 * can add data that defines a "shading material" for a renderer. Typically 
 * this consists of one or more UsdShadeOutput properties connected to outputs 
 * of nested Shader prims - though a context/client is free to add
 * any data that is suitable. We <b>strongly advise</b> that all contexts
 * adopt the convention that all properties be prefixed with a namespace
 * that identifies the context e.g. "token outputs:ri:surface.connect = 
 * </MyselfMaterial/previewSurface.outputs:surface". 
 *
 * ## Binding Materials
 *
 * In the UsdShading model, geometry expresses a binding to a single Material or
 * to a set of Materials partitioned by UsdGeomSubsets defined beneath the
 * geometry; it is legal to bind a Material at the root (or other sub-prim) of 
 * a model, and then bind a different Material to individual gprims, but the
 * meaning of inheritance and "ancestral overriding" of Material bindings is 
 * left to each render-target to determine.  Since UsdGeom has no concept of 
 * shading, we provide the API for binding and unbinding geometry on the API 
 * schema UsdShadeMaterialBindingAPI.
 *
 * ## Material Variation
 *
 * The entire power of USD VariantSets and all the other composition 
 * operators can leveraged when encoding shading variation.  
 * UsdShadeMaterial provides facilities for a particular way of building
 * "Material variants" in which neither the identity of the Materials themselves
 * nor the geometry Material-bindings need to change - instead we vary the
 * targeted networks, interface values, and even parameter values within
 * a single variantSet.  
 * See \ref UsdShadeMaterial_Variations "Authoring Material Variations" 
 * for more details.
 *
 * ## Materials Encapsulate their Networks in Namespace
 *
 * UsdShade requires that all of the shaders that "belong" to the Material 
 * live under the Material in namespace. This supports powerful, easy reuse
 * of Materials, because it allows us to *reference* a Material from one
 * asset (the asset might be a library of Materials) into another asset: USD 
 * references compose all descendant prims of the reference target into the 
 * referencer's namespace, which means that all of the referenced Material's 
 * shader networks will come along with the Material. When referenced in this
 * way, Materials can also be [instanced](http://openusd.org/docs/USD-Glossary.html#USDGlossary-Instancing), for ease of deduplication and compactness.
 * Finally, Material encapsulation also allows us to 
 * \ref UsdShadeMaterial_BaseMaterial "specialize" child materials from 
 * parent materials.
 *
 * For UsdShade schema domain any connectable child prim of UsdShadeMaterial 
 * must be either UsdShadeShader derived or UsdShadeNodeGraph derived but not 
 * UsdShadeMaterial, that is, UsdShadeMaterial can not be nested. It also must
 * not contain any imageable prims as its descendants (UsdGeomScope,
 * UsdGeomCamera, UsdGeomMesh etc).
 *
 * Other derived classes of UsdShadeNodeGraph from other schema domains may 
 * define their own stricter rules.
 */
export class Material extends NodeGraph {
  static readonly typeName: string = "Material"

  static get(stage: Stage, path: string): Material {
    return new Material(stage.getPrim(path), stage)
  }
  static define(stage: Stage, path: string): Material {
    return new Material(stage.definePrim(path, "Material"), stage)
  }

  isValid(): boolean {
    return super.isValid() && this.prim.isA(Material.typeName)
  }

  static getSchemaAttributeNames(includeInherited = true): string[] {
    const names = includeInherited
      ? ["outputs:surface","outputs:displacement","outputs:volume"]
      : ["outputs:surface","outputs:displacement","outputs:volume"]
    return names
  }

  /**
   * Represents the universal "surface" output terminal of a
   * material.
   */
  getSurfaceAttr(): Attribute {
    return this.prim.getAttr(UsdShadeTokens.outputsSurface)!
  }
  createSurfaceAttr(defaultValue?: unknown, writeSparsely = false): Attribute {
    return this._createAttr(UsdShadeTokens.outputsSurface, "token", false, "varying", defaultValue, writeSparsely)
  }

  /**
   * Represents the universal "displacement" output terminal of a 
   * material.
   */
  getDisplacementAttr(): Attribute {
    return this.prim.getAttr(UsdShadeTokens.outputsDisplacement)!
  }
  createDisplacementAttr(defaultValue?: unknown, writeSparsely = false): Attribute {
    return this._createAttr(UsdShadeTokens.outputsDisplacement, "token", false, "varying", defaultValue, writeSparsely)
  }

  /**
   * Represents the universal "volume" output terminal of a
   * material.
   */
  getVolumeAttr(): Attribute {
    return this.prim.getAttr(UsdShadeTokens.outputsVolume)!
  }
  createVolumeAttr(defaultValue?: unknown, writeSparsely = false): Attribute {
    return this._createAttr(UsdShadeTokens.outputsVolume, "token", false, "varying", defaultValue, writeSparsely)
  }

  // --(BEGIN CUSTOM CODE)--
  // OpenUSD v26.11.1 material.cpp:482-703: context-qualified terminals.
  createSurfaceOutput(context = ''): ShadeOutput { return this.createOutput(terminalName('surface', context), 'token') }
  createDisplacementOutput(context = ''): ShadeOutput { return this.createOutput(terminalName('displacement', context), 'token') }
  createVolumeOutput(context = ''): ShadeOutput { return this.createOutput(terminalName('volume', context), 'token') }
  getSurfaceOutput(context = ''): ShadeOutput { return this.getOutput(terminalName('surface', context)) }
  getDisplacementOutput(context = ''): ShadeOutput { return this.getOutput(terminalName('displacement', context)) }
  getVolumeOutput(context = ''): ShadeOutput { return this.getOutput(terminalName('volume', context)) }

  // UsdShadeMaterial::GetSurfaceOutputs / GetDisplacementOutputs /
  // GetVolumeOutputs (material.cpp:574-620,705-725): the universal terminal
  // output, then every authored output whose base name has a render-context
  // prefix and ends with the terminal name.
  getSurfaceOutputs(): ShadeOutput[] { return this.#getOutputsForTerminalName('surface') }
  getDisplacementOutputs(): ShadeOutput[] { return this.#getOutputsForTerminalName('displacement') }
  getVolumeOutputs(): ShadeOutput[] { return this.#getOutputsForTerminalName('volume') }

  #getOutputsForTerminalName(terminal: string): ShadeOutput[] {
    const outputs: ShadeOutput[] = []
    const universalOutput = this.getOutput(terminal)
    if (universalOutput.attr.isValid()) outputs.push(universalOutput)
    for (const baseName of getOutputNames(this._prim)) {
      // For an output to be considered specific to a renderContext, its base
      // name should be of the form "<renderContext>:...", so there must be
      // at least two components to the base name.
      const baseNameComponents = baseName.split(':')
      if (baseNameComponents.length < 2) continue
      if (baseNameComponents[baseNameComponents.length - 1] === terminal) {
        outputs.push(this.getOutput(baseName))
      }
    }
    return outputs
  }

  static is(prim: Prim): boolean { return prim.typeName === Material.typeName }

  // ---- Material variants ----

  // UsdShadeMaterial::GetEditContextForVariant (material.cpp:207-224): add
  // and select the materialVariant variant, then edit inside it (in layer,
  // the edit target's layer by default). Python's `with` context is the
  // returned UsdEditContext, to be closed. Variant authoring is
  // asynchronous here.
  async getEditContextForVariant(materialVariation: string, layer?: Layer): Promise<UsdEditContext> {
    const materialVariant = this._prim.getVariantSet(MATERIAL_VARIANT)
    let target = this._stage.getEditTarget()
    if (await materialVariant.addVariant(materialVariation)) {
      await materialVariant.setVariantSelection(materialVariation)
      target = materialVariant.getVariantEditTarget(layer)
    }
    return new UsdEditContext(this._stage, target)
  }

  // UsdShadeMaterial::GetMaterialVariant (material.cpp:243-247).
  getMaterialVariant(): UsdVariantSet {
    return this._prim.getVariantSet(MATERIAL_VARIANT)
  }

  // UsdShadeMaterial::CreateMasterMaterialVariant (material.cpp:250-362):
  // author on masterPrim a variant set (materialVariant by default) whose
  // variants select the same-named materialVariant of every material, all
  // of which must share one non-empty set of material variants. Materials
  // outside masterPrim's namespace are addressed by an over at the path
  // re-rooted under masterPrim.
  static async createMasterMaterialVariant(
    masterPrim: Prim, materials: readonly Prim[], masterVariantSetName = '',
  ): Promise<boolean> {
    if (!masterPrim?.isValid()) {
      console.error('MasterPrim is not a valid UsdPrim.')
      return false
    }
    const masterSetName = masterVariantSetName || MATERIAL_VARIANT
    const stage = masterPrim.getStage()
    let allMaterialVariants: string[] = []

    // Error Checking!
    if (materials.length === 0) {
      console.error('No material prims specified on which to operate.')
      return false
    }
    for (const material of materials) {
      if (!material?.isValid()) {
        console.error(`Unable to process invalid material: ${material?.getDescription()}`)
        return false
      }
      if (stage !== material.getStage()) {
        console.error(`All material prims to be controlled by masterPrim ${masterPrim.path} ` +
          `must originate on the same UsdStage as masterPrim.  Prim ${material.path} does not.`)
        return false
      }
      const materialVariants = material.getVariantSet(MATERIAL_VARIANT).getVariantNames()
      if (materialVariants.length === 0) {
        console.error('All Material prims to be switched by master materialVariant must ' +
          'actually possess a non-empty materialVariant themselves.  ' +
          `${material.path} does not.`)
        return false
      }
      if (allMaterialVariants.length === 0) {
        allMaterialVariants = materialVariants
      } else if (allMaterialVariants.length !== materialVariants.length ||
          allMaterialVariants.some((name, i) => name !== materialVariants[i])) {
        console.error('All Material prims to be switched by master materialVariant must ' +
          `possess the SAME material variants. ${material.path} has a different set of variants.`)
        return false
      }
    }

    const masterSet = masterPrim.getVariantSet(masterSetName)
    for (const varName of allMaterialVariants) {
      if (!await masterSet.addVariant(varName)) {
        console.error(`Unable to create Material variant ${varName} on prim ${masterPrim.path}. ` +
          'Aborting master materialVariant creation.')
        return false
      }
      await masterSet.setVariantSelection(varName)

      const ctxt = masterSet.getVariantEditContext()
      try {
        for (const material of materials) {
          if (!material.isValid()) {
            // Somehow, switching the variant caused this prim to expire.
            console.error(`Switching master variant ${masterSetName} to ${varName} caused one ` +
              `or more material prims to expire.  First such: ${material.getDescription()}.`)
            return false
          }
          // Here's the heart of the whole thing.
          const materialPath = SdfPath.fromString(material.path)
          const masterPath = SdfPath.fromString(masterPrim.path)
          if (materialPath.hasPrefix(masterPath)) {
            await material.getVariantSet(MATERIAL_VARIANT).setVariantSelection(varName)
          } else {
            const derivedPath = materialPath.replacePrefix(rootPathOf(materialPath), masterPath)
            const over = stage.overridePrim(derivedPath.pathString)
            if (over?.isValid()) {
              await over.getVariantSet(MATERIAL_VARIANT).setVariantSelection(varName)
            } else {
              console.error(`Unable to create over for Material prim ${derivedPath.pathString}, ` +
                'so cannot set its materialVariant')
              return false
            }
          }
        }
      } finally {
        ctxt.close()
      }
    }
    return true
  }

  static computeSurfaceSource(stage: Stage, materialPath: string, contexts: string | readonly string[] = ''): ConnectionSource | null {
    return computeTerminalSource(stage, materialPath, 'surface', contexts)
  }
  static computeDisplacementSource(stage: Stage, materialPath: string, contexts: string | readonly string[] = ''): ConnectionSource | null {
    return computeTerminalSource(stage, materialPath, 'displacement', contexts)
  }
  static computeVolumeSource(stage: Stage, materialPath: string, contexts: string | readonly string[] = ''): ConnectionSource | null {
    return computeTerminalSource(stage, materialPath, 'volume', contexts)
  }

  // ---- Base material (specializes-based inheritance) ----
  //
  // A material's "base material" is the material it specializes (its single
  // specialize arc resolving to a Material). Reference: usdShade/material.cpp
  // (Get/Set/Has/ClearBaseMaterial[Path]).

  // Authors a single specialize arc to `basePath`, or clears specializes when
  // empty (UsdShadeMaterial::SetBaseMaterialPath).
  async setBaseMaterialPath(basePath: string): Promise<void> {
    const specializes = this._prim.getSpecializes()
    if (!basePath) { await specializes.clearSpecializes(); return }
    await specializes.setSpecializes([basePath])
  }

  // Authors the base material from a Material handle (UsdShadeMaterial::SetBaseMaterial).
  async setBaseMaterial(baseMaterial: Material): Promise<void> {
    await this.setBaseMaterialPath(baseMaterial.path)
  }

  // Clears the base material (UsdShadeMaterial::ClearBaseMaterial).
  async clearBaseMaterial(): Promise<void> {
    await this.setBaseMaterialPath('')
  }

  // The path of the base material: the first specialize arc (direct child of
  // the prim index root, not crossing a reference) whose target resolves to a
  // Material on the stage. Mirrors UsdShadeMaterial::GetBaseMaterialPath /
  // FindBaseMaterialPathInPrimIndex. Returns null when there is none.
  getBaseMaterialPath(): string | null {
    const candidates = this._stage.getSpecializeArcTargets(this.path)
    for (const p of candidates) {
      const prim = this._stage.getPrim(p)
      if (prim && Material.is(prim)) return p
    }
    // Fallback for in-memory authoring stages with no retained prim index:
    // the directly-authored specializes whose target is a material.
    if (candidates.length === 0) {
      for (const p of this._prim.getSpecializes().getSpecializes()) {
        const prim = this._stage.getPrim(p)
        if (prim && Material.is(prim)) return p
      }
    }
    return null
  }

  // The base material as a Material handle, or null (UsdShadeMaterial::GetBaseMaterial).
  getBaseMaterial(): Material | null {
    const p = this.getBaseMaterialPath()
    if (!p) return null
    return new Material(this._stage._primHandle(p), this._stage)
  }

  // True when this material specializes a base material (UsdShadeMaterial::HasBaseMaterial).
  hasBaseMaterial(): boolean {
    return this.getBaseMaterialPath() !== null
  }
}


// UsdShadeTokens->materialVariant.
const MATERIAL_VARIANT = 'materialVariant'

// _GetRootPath (material.cpp:226-241): the root prim path of a prim path.
function rootPathOf(path: SdfPath): SdfPath {
  if (path.pathString === '/') return path
  let root = path
  while (!root.isRootPrimPath()) root = root.getParentPath()
  return root
}

function terminalName(terminal: string, context: string): string {
  return context ? `${context}:${terminal}` : terminal
}

// OpenUSD v26.11.1 material.cpp:489-573. Preserve context priority, then
// universal fallback; only shader outputs may become renderer terminals.
function computeTerminalSource(stage: Stage, path: string, terminal: string, contexts: string | readonly string[]): ConnectionSource | null {
  const ordered = typeof contexts === 'string' ? [contexts] : [...contexts]
  if (!ordered.includes('')) ordered.push('')
  for (const context of ordered) {
    const attrs = getValueProducingAttributes(stage, `${path}.outputs:${terminalName(terminal, context)}`, true)
    if (attrs.length) return parseSourcePath(attrs[0]!.getPath())
  }
  return null
}

// material.cpp:726-757: Materials are containers with encapsulation, whose
// connections follow the DerivedContainerNodes rules.
class MaterialConnectableAPIBehavior extends ConnectableAPIBehavior {
  constructor() { super(true /*isContainer*/, true /*requiresEncapsulation*/) }
  override canConnectInputToSource(
    stage: Stage, inputPath: string, source: BehaviorConnectionSource,
  ): BehaviorCanConnectResult {
    return this._canConnectInputToSource(stage, inputPath, source,
      ConnectableNodeTypes.DerivedContainerNodes)
  }
  override canConnectOutputToSource(
    stage: Stage, outputPath: string, source: BehaviorConnectionSource,
  ): BehaviorCanConnectResult {
    return this._canConnectOutputToSource(stage, outputPath, source,
      ConnectableNodeTypes.DerivedContainerNodes)
  }
}
registerConnectableAPIBehavior(TfType.findByName('UsdShadeMaterial'), new MaterialConnectableAPIBehavior())

